import {getAsset} from '../assets/catalog.js';
import {defaultCollider2d,defaultRigidbody2d,defaultController2d} from './physics-2d.js';
export function createBundledPhysicsScene2d(){
 const entities=[];
 const sprite=(id,x,y,options={})=>{const asset=getAsset(id);if(!asset)throw Error('Sprite intégré absent : '+id);const e={id:entities.length+1,name:asset.name,type:'prefab',assetId:id,x,y,w:asset.width,h:asset.height,color:'#83bdd2',animation:'idle',hp:100,hideLabelInPlay:true,collision3d:false,...options};entities.push(e);return e};
 sprite('demo-platformer-backdrop',-70,-100,{w:2380,h:900,name:'Courrier des toits · horizon',hierarchyGroup:'Arrière-plan'});
 const player=sprite('free-platformer-art-deluxe-p1-stand',70,440,{name:'Le coursier',hierarchyGroup:'Joueur',adventure:{title:'Courrier des toits',combatEnabled:false,hint:'Trois colis sur les toits · gemmes : points de reprise · E au bureau pour livrer.',items:[],notes:[]},controller2d:{...defaultController2d(),mode:'platformer',jumpSpeed:470,demo:{id:'platformer',title:'Courrier des toits',description:'Trois colis sur un parcours de sauts, des caisses physiques et des points de reprise avant la livraison.',features:['Gravité et saut','Colliders et corps physiques','Collecte et objectifs','Points de reprise','Livraison et victoire']}},rigidbody2d:defaultRigidbody2d(),collider2d:defaultCollider2d()});
 const platform=(x,y,length,group='Parcours')=>{for(let i=0;i<length;i++)sprite(i===0?'free-platformer-art-deluxe-grassleft':i===length-1?'free-platformer-art-deluxe-grassright':'free-platformer-art-deluxe-grassmid',x+i*70,y,{name:group,hierarchyGroup:group,collision3d:true,collider2d:defaultCollider2d()})};
 platform(0,560,12,'Départ · apprendre à sauter');platform(910,560,10,'Secteur des caisses');platform(1680,560,8,'Approche de la livraison');
 for(const [x,y,count] of [[280,490,3],[420,420,3],[1050,490,3],[1190,420,3],[1260,350,2],[1750,490,3],[1820,420,3]])platform(x,y,count,'Toits · itinéraire des colis');
 for(const [i,[x,y]] of [[440,160],[1120,180],[1540,250]].entries())sprite('free-platformer-art-deluxe-box',x,y,{name:'Caisse physique '+(i+1),w:48,h:48,hierarchyGroup:'Corps physiques',collision3d:true,collider2d:defaultCollider2d(),rigidbody2d:{...defaultRigidbody2d(),mass:i+1,restitution:.08}});
 for(const [i,[x,y]] of [[500,380],[1300,310],[1880,380]].entries()){
  const parcel=sprite('free-platformer-art-deluxe-box',x,y,{name:'Colis '+(i+1),w:30,h:30,hierarchyGroup:'Colis à livrer',hideLabelInPlay:false});
  parcel.sequence={enabled:true,event:'enter',radius:48,once:true,instructions:[{type:'addVariable',key:'roofParcels',value:1},{type:'addObjectiveProgress',key:'roofCollect',value:1},{type:'emitFx',value:'heal',color:'#ffe0a0'},{type:'setVisibility',value:false}]};
 }
 const checkpoint=(x,name)=>{const flag=sprite('free-platformer-art-deluxe-gemblue',x,510,{name,w:24,h:30,hierarchyGroup:'Points de reprise',hideLabelInPlay:false});flag.sequence={enabled:true,event:'enter',radius:60,once:true,instructions:[{type:'setCheckpoint',targetRole:'player'},{type:'message',value:'Point de reprise atteint · les colis déjà ramassés sont conservés.'}]}};checkpoint(995,'Point de reprise 1');checkpoint(1745,'Point de reprise 2');
 for(let x=0;x<2310;x+=70){const rescue={id:entities.length+1,type:'object',name:'Sécurité · chute',x,y:750,w:70,h:70,color:'#7395a8',visible:false,collision3d:false,hideLabelInPlay:true,hierarchyGroup:'Sécurité du parcours',sequence:{enabled:true,event:'enter',radius:60,once:false,instructions:[{type:'restoreCheckpoint'}]}};entities.push(rescue)}
 for(const x of [-70,2240])entities.push({id:entities.length+1,type:'object',name:'Limite du parcours',x,y:-200,w:70,h:1100,visible:false,collision3d:true,hideLabelInPlay:true,hierarchyGroup:'Sécurité du parcours',collider2d:defaultCollider2d()});
 const delivery=sprite('free-platformer-art-deluxe-gemblue',2140,490,{name:'Bureau de livraison · E',adventureInteractable:{label:'Livrer les trois colis',radius:110},w:42,h:48,hierarchyGroup:'Arrivée',hideLabelInPlay:false});
 delivery.sequence={enabled:true,event:'interact',key:'e',radius:110,once:false,branches:[{conditions:[{type:'variable',key:'roofParcels',operator:'==',value:3}],instructions:[{type:'completeObjective',key:'roofDelivery'},{type:'winGame',value:'Trois colis livrés. Le quartier a reçu son courrier !'}]}],elseInstructions:[{type:'message',value:'Il faut les trois colis avant de terminer la tournée.'}]};
 player.sequence={enabled:true,event:'start',once:true,instructions:[{type:'setVariable',key:'roofParcels',value:0},{type:'setObjective',key:'roofCollect',value:'Récupérer les trois colis sur les toits',total:3},{type:'setObjective',key:'roofDelivery',value:'Livrer les colis au bureau',total:1},{type:'setCheckpoint',targetRole:'player'},{type:'message',value:'COURRIER DES TOITS · Q/D ou flèches · Espace : sauter · Maj : courir · E : livrer. Les gemmes marquent les points de reprise.'}]};
 return {entities,selected:[player.id],nextId:entities.length+1,camera:{x:40,y:0,zoom:.85},genre:'platformer',guide:'Courrier des toits · Q/D ou flèches · Espace/Z/W : sauter · Maj : courir · E : livrer les trois colis. Une chute ramène au dernier point de reprise.'};
}
